// Planted problems for the health check: one email per change of state, never one per run, and an
// alert that fails to send is retried rather than lost.

import { beforeEach, describe, expect, it } from "vitest";
import { memoryAdapter } from "@dustinedwards/site-api/testing";

import { runHealth } from "~/lib/health.server";
import { clearTokenCache } from "~/lib/novels/repo.server";
import { addPerson, resetDb, testEnv } from "./env";
import { fakeNovels, githubStyleKey } from "./novels";
import { connectedEnv, fakeSite, SITE_ORIGIN } from "./site";

type Sent = { subject: string; text: string; to: string };

function mailbox(fail = false) {
  const sent: Sent[] = [];
  const EMAIL = {
    async send(message: Sent) {
      if (fail) throw new Error("send failed");
      sent.push(message);
      return { messageId: `m${sent.length}` };
    },
  } as unknown as SendEmail;
  return { sent, EMAIL };
}

const certsOk = async () => Response.json({ keys: [{ kid: "k" }] });
const certsDown = async () => new Response("down", { status: 503 });

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
});

describe("health", () => {
  it("sends nothing on a first run where every check passes", async () => {
    const box = mailbox();
    const { results, emailed } = await runHealth({ ...testEnv, EMAIL: box.EMAIL }, certsOk);
    expect(results.every((r) => r.ok)).toBe(true);
    expect(emailed).toBe(false);
    expect(box.sent).toHaveLength(0);
  });

  it("sends one email when a check starts failing, and none while it stays failing", async () => {
    const box = mailbox();
    const env = { ...testEnv, EMAIL: box.EMAIL };
    await runHealth(env, certsOk);
    await runHealth(env, certsDown);
    await runHealth(env, certsDown);
    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]!.subject).toBe("Carrel: 1 check failing");
    expect(box.sent[0]!.text).toContain("FAIL access-keys");
    expect(box.sent[0]!.to).toBe("owner@test.invalid");
  });

  it("sends one email on recovery", async () => {
    const box = mailbox();
    const env = { ...testEnv, EMAIL: box.EMAIL };
    await runHealth(env, certsDown);
    await runHealth(env, certsOk);
    expect(box.sent.map((m) => m.subject)).toEqual(["Carrel: 1 check failing", "Carrel: all checks pass"]);
  });

  it("flags a database with no Owner", async () => {
    await resetDb();
    const box = mailbox();
    await runHealth({ ...testEnv, EMAIL: box.EMAIL }, certsOk);
    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]!.text).toContain("FAIL owner");
  });

  it("flags a missing ACCESS_AUD and a placeholder alert address", async () => {
    const box = mailbox();
    await runHealth({ ...testEnv, ACCESS_AUD: "", ALERT_EMAIL: "alerts@example.com", EMAIL: box.EMAIL }, certsOk);
    expect(box.sent[0]!.text).toMatch(/FAIL config: Missing or placeholder: ACCESS_AUD, ALERT_EMAIL/);
  });

  it("keeps the alert pending when the email fails, and sends it on the next run", async () => {
    const failing = mailbox(true);
    const first = await runHealth({ ...testEnv, EMAIL: failing.EMAIL }, certsDown);
    expect(first.emailed).toBe(false);

    const working = mailbox();
    const second = await runHealth({ ...testEnv, EMAIL: working.EMAIL }, certsDown);
    expect(second.emailed).toBe(true);
    expect(working.sent).toHaveLength(1);
  });
});

// Stage 2: each site's key and its conformance to the site-api contract (design section 7, "Health":
// a changed schema hash sends one email).
describe("site health", () => {
  function through(site: ReturnType<typeof fakeSite>, drift = false) {
    return async (url: string, init?: RequestInit) => {
      if (!url.startsWith(SITE_ORIGIN)) return certsOk();
      const response = await site.fetch(url, init);
      if (!drift || !url.endsWith("/meta") || !response.ok) return response;
      const meta = (await response.json()) as Record<string, unknown>;
      return Response.json({ ...meta, schemaHash: "f".repeat(64), packageVersion: "0.2.0" });
    };
  }

  it("counts a site with no key as not connected, which is not a failure", async () => {
    const { results } = await runHealth({ ...testEnv, EMAIL: mailbox().EMAIL }, certsOk);
    expect(results.find((r) => r.name === "site-dustinedwards")).toEqual({
      name: "site-dustinedwards",
      ok: true,
      detail: "Not connected: No SITE_DUSTINEDWARDS_KEY set.",
    });
  });

  it("PLANT: flags a key too short to be the site's", async () => {
    const box = mailbox();
    await runHealth({ ...connectedEnv({ SITE_DUSTINEDWARDS_KEY: "short" }), EMAIL: box.EMAIL }, certsOk);
    expect(box.sent[0]!.text).toMatch(/FAIL site-dustinedwards: SITE_DUSTINEDWARDS_KEY is shorter than 32/);
  });

  it("passes a conforming site, and its write probe changes nothing there", async () => {
    const site = fakeSite();
    const box = mailbox();
    const { results } = await runHealth({ ...connectedEnv(), EMAIL: box.EMAIL }, through(site));
    expect(results.find((r) => r.name === "site-dustinedwards")?.ok).toBe(true);
    expect(box.sent).toHaveLength(0);
    expect(site.adapter.store.size).toBe(0);
  });

  it("includes the mentions group when the site declares it, and its probe changes nothing there", async () => {
    const site = fakeSite();
    const id = site.adapter.receiveMention({ sourceUrl: "https://a.example/post", targetId: "first-post" });
    const before = structuredClone(site.adapter.mentionStore.get(id));
    const box = mailbox();
    const { results } = await runHealth({ ...connectedEnv(), EMAIL: box.EMAIL }, through(site));
    expect(results.find((r) => r.name === "site-dustinedwards")?.ok).toBe(true);
    const asked = site.requests.filter((r) => r.includes("/mentions"));
    // The probe ran against the real mention (a stale version, so refused), and nothing deleted or swept it.
    expect(asked).toContain(`POST /api/carrel/v1/mentions/${id}/decide`);
    expect(asked).not.toContain(`DELETE /api/carrel/v1/mentions/${id}`);
    expect(site.adapter.mentionStore.get(id)).toEqual(before);
    expect(site.adapter.purged).toEqual([]);
    expect(box.sent).toHaveLength(0);
  });

  it("PLANT: a site that decides a mention it does not hold is flagged, by the mentions check", async () => {
    const site = fakeSite();
    site.adapter.mentions!.decide = async () => ({ status: "approved", version: "m9", purged: null });
    const box = mailbox();
    await runHealth({ ...connectedEnv(), EMAIL: box.EMAIL }, through(site));
    expect(box.sent[0]!.text).toMatch(/FAIL site-dustinedwards: dustinedwards\.info does not conform\. mention decide of an unknown id/);
  });

  it("a site without the mentions group still conforms: its mentions routes answer 501", async () => {
    const site = fakeSite(memoryAdapter({ mentions: false }));
    const { results } = await runHealth({ ...connectedEnv(), EMAIL: mailbox().EMAIL }, through(site));
    expect(results.find((r) => r.name === "site-dustinedwards")?.ok).toBe(true);
  });

  it("PLANT: a changed schema hash sends one email, and none while it stays changed", async () => {
    const site = fakeSite();
    const box = mailbox();
    const env = { ...connectedEnv(), EMAIL: box.EMAIL };
    await runHealth(env, through(site));
    await runHealth(env, through(site, true));
    await runHealth(env, through(site, true));
    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]!.text).toMatch(/FAIL site-dustinedwards: dustinedwards\.info does not conform\. meta: answers with this contract's schema hash: schema hash ffffffffffff/);
  });

  it("PLANT: flags a site that holds a different key", async () => {
    const site = fakeSite();
    const box = mailbox();
    await runHealth({ ...connectedEnv({ SITE_DUSTINEDWARDS_KEY: "another-key-of-the-right-length-0123456789" }), EMAIL: box.EMAIL }, through(site));
    expect(box.sent[0]!.text).toContain("FAIL site-dustinedwards");
  });
});

// Stage 4: the GitHub App for the novels repository (design section 5, "Health": the GitHub App token).
describe("novels health", () => {
  beforeEach(() => clearTokenCache());

  function through(gh: ReturnType<typeof fakeNovels>) {
    return async (url: string, init?: RequestInit) => (url.startsWith("https://api.github.com") ? gh.fetch(url, init) : certsOk());
  }

  it("counts an App not set up yet as not connected, which is not a failure", async () => {
    const { results } = await runHealth({ ...testEnv, EMAIL: mailbox().EMAIL }, certsOk);
    expect(results.find((r) => r.name === "novels")).toMatchObject({ ok: true, detail: expect.stringMatching(/^Not connected: /) });
  });

  it("PLANT: flags half a setup, an App id with no key", async () => {
    const box = mailbox();
    await runHealth({ ...testEnv, NOVELS_APP_ID: "123", EMAIL: box.EMAIL }, certsOk);
    expect(box.sent[0]!.text).toContain("FAIL novels: NOVELS_APP_PRIVATE_KEY is missing");
  });

  it("passes when the App gets a token for the repository", async () => {
    const key = await githubStyleKey();
    const { results } = await runHealth(
      { ...testEnv, NOVELS_APP_ID: "123", NOVELS_APP_PRIVATE_KEY: key.pkcs1Pem, EMAIL: mailbox().EMAIL },
      through(fakeNovels()),
    );
    expect(results.find((r) => r.name === "novels")).toEqual({ name: "novels", ok: true, detail: "The GitHub App can write to DrDustinEdwards/novels." });
  });

  it("PLANT: flags an App GitHub will not answer for", async () => {
    const key = await githubStyleKey();
    const box = mailbox();
    const refused = async (url: string) => (url.startsWith("https://api.github.com") ? new Response("{}", { status: 404 }) : certsOk());
    await runHealth({ ...testEnv, NOVELS_APP_ID: "123", NOVELS_APP_PRIVATE_KEY: key.pkcs1Pem, EMAIL: box.EMAIL }, refused);
    expect(box.sent[0]!.text).toContain("FAIL novels: The GitHub App could not reach DrDustinEdwards/novels: GitHub did not find the App's installation");
  });
});

test/mentions.test.ts.source:
// The webmention queue (site-api v0.5.0 mentions group): the Owner's alone to read and to decide, each
// mention its own write with its own authorship row, one failing never stopping the rest, and every
// refusal (a role, a stale version, a missing mention, a site with no mentions) leaving the site and the
// record as they were. Planted refusals assert the site was never asked.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { memoryAdapter } from "@dustinedwards/site-api/testing";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { decideMentions, listMentions, MAX_MENTION_BATCH, mentionsOffered, parseTargets, sweepMentions } from "~/lib/mentions.server";
import { requireSiteProject } from "~/lib/projects.server";
import { action as mentionsApi } from "~/routes/mentions.api";
import { loader as mentionsLoader } from "~/routes/mentions";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
type Site = ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let site: Site;
let env: Env;
let ids: { pending: string; second: string; approved: string; failed: string; unverified: string; oldFailed: string; oldRejected: string };

const DAY = 24 * 60 * 60 * 1000;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
  start(fakeSite());
});

function start(next: Site) {
  site = next;
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
  const ago = (days: number) => new Date(Date.now() - days * DAY);
  const send = (fields: Parameters<Site["adapter"]["receiveMention"]>[0]) => site.adapter.receiveMention(fields);
  ids = {
    pending: send({ sourceUrl: "https://a.example/one", targetId: "first-post", authorName: "Ada", excerpt: "One.", receivedAt: ago(1) }),
    second: send({ sourceUrl: "https://b.example/two", targetId: "first-post", authorName: "Bo", excerpt: "Two.", receivedAt: ago(2) }),
    approved: send({ sourceUrl: "https://c.example/three", targetId: "second-post", status: "approved", receivedAt: ago(3) }),
    failed: send({ sourceUrl: "https://d.example/four", targetId: "first-post", status: "failed", receivedAt: ago(4) }),
    unverified: send({ sourceUrl: "https://e.example/five", targetId: "first-post", status: "unverified", receivedAt: ago(0) }),
    oldFailed: send({ sourceUrl: "https://f.example/six", targetId: "first-post", status: "failed", receivedAt: ago(60) }),
    oldRejected: send({ sourceUrl: "https://g.example/seven", targetId: "second-post", status: "rejected", receivedAt: ago(200) }),
  };
}

async function as(email: string, action: "read_mentions" | "decide_mention" | "read" = "read_mentions") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, action) };
}

/** The version the page would have shown for a mention. */
const versionOf = (id: string) => site.adapter.mentionStore.get(id)!.version;
const target = (id: string) => ({ id, version: versionOf(id), status: site.adapter.mentionStore.get(id)!.status });
const decisions = async () =>
  (
    await testEnv.DB.prepare(
      "SELECT mention_id AS mentionId, action, status_before AS before, status_after AS after, change_id AS changeId, person_id AS who, client FROM mention_decisions ORDER BY id",
    ).all<{ mentionId: string | null; action: string; before: string | null; after: string | null; changeId: string; who: number; client: string | null }>()
  ).results;
const writes = () => site.requests.filter((r) => !r.startsWith("GET"));

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  return 200;
}

describe("roles: the queue is the Owner's alone (carrel/design.md: the inbox belongs to Dustin alone)", () => {
  it("PLANT: refuses an Editor and a Reader who open the queue, and the site is never asked", async () => {
    for (const email of ["editor@test.invalid", "reader@test.invalid"]) {
      expect(await refusal(as(email))).toBe(403);
    }
    expect(site.requests).toEqual([]);
  });

  it("PLANT: refuses an Editor and a Reader who decide, delete or sweep, and nothing on the site or in the record moves", async () => {
    const before = structuredClone([...site.adapter.mentionStore.values()]);
    for (const email of ["editor@test.invalid", "reader@test.invalid"]) {
      const viewer = await viewerFor(email);
      const project = await requireSiteProject(testEnv.DB, viewer, SLUG, "read");
      for (const op of ["approve", "reject", "delete"] as const) {
        expect(await refusal(decideMentions(env, project, { viewer }, op, [target(ids.pending)], site.fetch)), `${email} ${op}`).toBe(403);
      }
      expect(await refusal(sweepMentions(env, project, { viewer }, site.fetch)), `${email} sweep`).toBe(403);
      expect(await refusal(listMentions(env, project, {}, site.fetch)), `${email} list`).toBe(403);
      expect(await refusal(mentionsOffered(env, project, site.fetch)), `${email} offered`).toBe(403);
    }
    expect(site.requests).toEqual([]);
    expect([...site.adapter.mentionStore.values()]).toEqual(before);
    expect(await decisions()).toEqual([]);
  });

  it("PLANT: the screen's loader and the write endpoint refuse an Editor before the site is asked", async () => {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("editor@test.invalid"));
    context.set(nonceContext, "n");
    expect(await refusal(Promise.resolve(mentionsLoader({ request: new Request(`https://carrel.test/p/${SLUG}/mentions`), params: { project: SLUG }, context } as never)))).toBe(403);
    const body = new FormData();
    body.set("op", "delete");
    body.set("items", JSON.stringify([target(ids.pending)]));
    const response = (await mentionsApi({ request: new Request(`https://carrel.test/p/${SLUG}/mentions/api`, { method: "POST", body }), params: { project: SLUG }, context } as never)) as Response;
    expect(response.status).toBe(403);
    expect(await response.json()).toEqual({ error: "Deciding mentions is the Owner's step." });
    expect(site.requests).toEqual([]);
    expect(site.adapter.mentionStore.has(ids.pending)).toBe(true);
  });

  it("answers 404, not 403, for a person with no role on the project", async () => {
    await addPerson("outsider@test.invalid");
    expect(await refusal(as("outsider@test.invalid"))).toBe(404);
  });
});

describe("reading the queue", () => {
  it("opens on Pending, with the counts of the whole queue and what a sweep would remove", async () => {
    const { project } = await as("owner@test.invalid");
    const { filter, list } = await listMentions(env, project, {}, site.fetch);
    expect(filter).toBe("pending");
    expect(list.items.map((m) => m.id).sort()).toEqual([ids.pending, ids.second].sort());
    expect(list.counts).toEqual({ unverified: 1, pending: 2, approved: 1, rejected: 1, failed: 2 });
    expect(list.expiring).toEqual({ failed: 1, rejected: 1 });
  });

  it("opens on All when nothing is pending, and filters when asked", async () => {
    const { project } = await as("owner@test.invalid");
    await decideMentions(env, project, { viewer: (await as("owner@test.invalid")).viewer }, "reject", [target(ids.pending), target(ids.second)], site.fetch);
    const opened = await listMentions(env, project, {}, site.fetch);
    expect(opened.filter).toBe("all");
    expect(opened.list.items).toHaveLength(7);
    const failed = await listMentions(env, project, { filter: "failed" }, site.fetch);
    expect(failed.list.items.map((m) => m.status)).toEqual(["failed", "failed"]);
  });

  it("says why when the site does not receive mentions through Carrel", async () => {
    start(fakeSite(memoryAdapter({ mentions: false })));
    const { project } = await as("owner@test.invalid");
    expect(await mentionsOffered(env, project, site.fetch)).toEqual({ offered: false, reason: "This site does not receive webmentions through Carrel yet." });
  });

  it("says why when the site has no key", async () => {
    const { project } = await as("owner@test.invalid");
    const answer = await mentionsOffered({ ...testEnv }, project, site.fetch);
    expect(answer).toMatchObject({ offered: false });
  });
});

describe("deciding", () => {
  it("approves at the version the person saw, purges through the site, and writes one authorship row with the site's change id", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const decide = vi.spyOn(site.adapter.mentions!, "decide");
    const results = await decideMentions(env, project, { viewer }, "approve", [target(ids.pending)], site.fetch);
    expect(results).toEqual([{ id: ids.pending, ok: true, message: "Approved." }]);
    expect(site.adapter.mentionStore.get(ids.pending)!.status).toBe("approved");
    expect(site.adapter.purged).toEqual(["first-post"]);
    const log = await decisions();
    expect(log).toEqual([{ mentionId: ids.pending, action: "approve", before: "pending", after: "approved", changeId: decide.mock.calls[0]![1].changeId, who: viewer.id, client: null }]);
  });

  it("credits the AI client in the record when one decides", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    await decideMentions(env, project, { viewer, client: "Claude" }, "reject", [target(ids.pending)], site.fetch);
    expect((await decisions())[0]).toMatchObject({ action: "reject", after: "rejected", client: "Claude" });
  });

  it("deletes, with no status after, and records it", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const results = await decideMentions(env, project, { viewer }, "delete", [target(ids.failed)], site.fetch);
    expect(results).toEqual([{ id: ids.failed, ok: true, message: "Deleted." }]);
    expect(site.adapter.mentionStore.has(ids.failed)).toBe(false);
    expect(await decisions()).toMatchObject([{ mentionId: ids.failed, action: "delete", before: "failed", after: null }]);
  });

  it("PLANT: refuses a stale version for that mention alone, writes no row for it, and decides the rest", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const seen = [target(ids.pending), target(ids.second)];
    // Another door decides the first one after the page loaded.
    await decideMentions(env, project, { viewer }, "reject", [target(ids.pending)], site.fetch);
    const results = await decideMentions(env, project, { viewer }, "approve", seen, site.fetch);
    expect(results[0]).toMatchObject({ id: ids.pending, ok: false });
    expect(results[0]!.message).toMatch(/changed on the site since the page loaded/);
    expect(results[1]).toMatchObject({ id: ids.second, ok: true });
    expect(site.adapter.mentionStore.get(ids.pending)!.status).toBe("rejected");
    expect(site.adapter.mentionStore.get(ids.second)!.status).toBe("approved");
    expect((await decisions()).map((r) => [r.mentionId, r.action])).toEqual([[ids.pending, "reject"], [ids.second, "approve"]]);
  });

  it("PLANT: one missing, one the site refuses and one fine: each has its own outcome and the fine one lands", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const gone = target(ids.second);
    site.adapter.mentionStore.delete(ids.second);
    const results = await decideMentions(env, project, { viewer }, "approve", [gone, target(ids.unverified), target(ids.pending)], site.fetch);
    expect(results.map((r) => [r.id, r.ok])).toEqual([[ids.second, false], [ids.unverified, false], [ids.pending, true]]);
    expect(results[0]!.message).toMatch(/no longer has this mention/);
    expect(results[1]!.message).toMatch(/cannot be decided/);
    expect(site.adapter.mentionStore.get(ids.unverified)!.status).toBe("unverified");
    expect(await decisions()).toHaveLength(1);
  });

  it("reports a site error for one mention without stopping the next, and writes no row for it", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const real = site.adapter.mentions!.decide;
    let calls = 0;
    site.adapter.mentions!.decide = async (id, input) => {
      if (++calls === 1) throw new Error("database is locked");
      return real(id, input);
    };
    const quiet = vi.spyOn(console, "error").mockImplementation(() => {});
    const results = await decideMentions(env, project, { viewer }, "approve", [target(ids.pending), target(ids.second)], site.fetch);
    quiet.mockRestore();
    expect(results[0]).toMatchObject({ ok: false, message: "The site did not accept this change. The mention was left as it was." });
    expect(results[1]).toMatchObject({ ok: true });
    expect(await decisions()).toHaveLength(1);
  });

  it("says when the site could not clear its cache, since the decision still stands", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const real = site.adapter.mentions!.decide;
    site.adapter.mentions!.decide = async (id, input) => ({ ...(await real(id, input)), purged: false });
    const [result] = await decideMentions(env, project, { viewer }, "approve", [target(ids.pending)], site.fetch);
    expect(result).toMatchObject({ ok: true });
    expect(result!.message).toMatch(/could not clear its cache/);
    expect(await decisions()).toHaveLength(1);
  });

  it("PLANT: answers a site with no mentions in plain words, writes nothing and records nothing", async () => {
    start(fakeSite(memoryAdapter({ mentions: false })));
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const results = await decideMentions(env, project, { viewer }, "approve", [{ id: "1", version: "m1", status: "pending" }], site.fetch);
    expect(results).toEqual([{ id: "1", ok: false, message: "The site does not moderate mentions through Carrel yet." }]);
    expect(await decisions()).toEqual([]);
  });

  it("says the decision happened when only the record failed", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    // A person the database does not hold cannot be recorded (the person_id foreign key), after the site has written.
    const quiet = vi.spyOn(console, "error").mockImplementation(() => {});
    const [result] = await decideMentions(env, project, { viewer: { ...viewer, id: 99_999 } }, "reject", [target(ids.pending)], site.fetch);
    quiet.mockRestore();
    expect(result!.ok).toBe(true);
    expect(result!.message).toMatch(/could not save the record/);
    expect(site.adapter.mentionStore.get(ids.pending)!.status).toBe("rejected");
    expect(await decisions()).toEqual([]);
  });

  it("refuses an empty choice, and too many, before the site is asked", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    expect(await refusal(decideMentions(env, project, { viewer }, "approve", [], site.fetch))).toBe(400);
    const many = Array.from({ length: MAX_MENTION_BATCH + 1 }, (_, i) => ({ id: String(i + 1), version: "m1", status: "pending" }));
    expect(await refusal(decideMentions(env, project, { viewer }, "approve", many, site.fetch))).toBe(400);
    expect(site.requests).toEqual([]);
  });

  it("does not send an id or a version a site could not hold", () => {
    const parsed = parseTargets([
      { id: "12", version: "m1", status: "pending" },
      { id: "12", version: "m1", status: "pending" },
      { id: "../x", version: "m1", status: "pending" },
      { id: "13", version: "", status: "pending" },
      { id: "14", version: "m1", status: "bogus" },
      "nonsense",
    ]);
    expect(parsed.targets).toEqual([{ id: "12", version: "m1", status: "pending" }]);
    expect(parsed.invalid).toEqual(["../x", "13", "14", "(no id)"]);
  });
});

describe("sweeping", () => {
  it("removes what the site says is expired, keeps the rest, and records one row with no mention id", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const result = await sweepMentions(env, project, { viewer }, site.fetch);
    expect(result).toMatchObject({ ok: true, removed: { failed: 1, rejected: 1 }, recorded: true });
    expect(site.adapter.mentionStore.has(ids.oldFailed)).toBe(false);
    expect(site.adapter.mentionStore.has(ids.oldRejected)).toBe(false);
    expect(site.adapter.mentionStore.has(ids.failed)).toBe(true);
    expect(site.adapter.mentionStore.has(ids.pending)).toBe(true);
    expect(await decisions()).toMatchObject([{ mentionId: null, action: "sweep", before: null, after: null, who: viewer.id }]);
  });

  it("PLANT: a site with no mentions answers in plain words, and nothing is recorded", async () => {
    start(fakeSite(memoryAdapter({ mentions: false })));
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    expect(await sweepMentions(env, project, { viewer }, site.fetch)).toEqual({ ok: false, message: "The site does not moderate mentions through Carrel yet." });
    expect(await decisions()).toEqual([]);
  });

  it("goes through the endpoint for the Owner as JSON", async () => {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("owner@test.invalid"));
    context.set(nonceContext, "n");
    const body = new FormData();
    body.set("op", "sweep");
    const response = (await mentionsApi({ request: new Request(`https://carrel.test/p/${SLUG}/mentions/api`, { method: "POST", body }), params: { project: SLUG }, context } as never)) as Response;
    expect(response.status).toBe(200);
    expect(((await response.json()) as { sweep: unknown }).sweep).toMatchObject({ ok: true, removed: { failed: 1, rejected: 1 } });
    expect(writes()).toEqual(["POST /api/carrel/v1/mentions/sweep"]);
  });
});

describe("the migration", () => {
  it("PLANT: refuses a record that names no mention for anything but a sweep, and a status after a delete", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const insert = (mention: string | null, action: string, after: string | null) =>
      testEnv.DB.prepare("INSERT INTO mention_decisions (project_id, mention_id, person_id, action, status_after, change_id) VALUES (?, ?, ?, ?, ?, ?)")
        .bind(project.id, mention, viewer.id, action, after, crypto.randomUUID())
        .run();
    await expect(insert(null, "approve", "approved")).rejects.toThrow();
    await expect(insert("1", "approve", null)).rejects.toThrow();
    await expect(insert("1", "approve", "spam")).rejects.toThrow();
    await expect(insert("1", "launch", "approved")).rejects.toThrow();
    await insert(null, "sweep", null);
    await insert("1", "delete", null);
    expect((await decisions()).map((r) => r.action)).toEqual(["sweep", "delete"]);
  });
});

test/door.test.ts.source:
// The two doors (design decision 7, corrected 2026-09-27). The browser door is carrel.dustinedwards.info
// behind Access; the AI door is carrel-mcp.dustinedwards.info, an OAuth authorization server of its
// own with Cloudflare Access for SaaS as the sign-in. They are told apart by hostname, never by email.
//
// The AI door is driven end to end here: a CIMD client, the consent page, Access's sign-in (a fake
// Access for SaaS: its token and keys endpoints, answered through the stubbed fetch), the token
// endpoint, and a tool call with the token. Each planted refusal must end without a grant.

import { createExecutionContext } from "cloudflare:test";
import { createLocalJWKSet, exportJWK, generateKeyPair, SignJWT, type JWK } from "jose";
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { aiDoor, isMcpHost } from "~/lib/mcp/door";

import { gate } from "../workers/gate";
import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { MCP_HOST, modernRequest, readMessage, type ToolCallResult } from "./mcp-client";
import { connectedEnv, fakeSite } from "./site";

const TEAM = "https://test-team.cloudflareaccess.com";
const BROWSER_AUD = "test-audience-tag";
const SAAS_CLIENT = "carrel-saas-client";
const SAAS_ISSUER = `${TEAM}/cdn-cgi/access/sso/oidc/${SAAS_CLIENT}`;
const DOOR = `https://${MCP_HOST}`;
const CLIENT_ID = "https://client.test/oauth/claude-code.json";
const REDIRECT = "https://client.test/callback";
const RESOURCE = `${DOOR}/mcp`;
const VERIFIER = "the-mcp-clients-own-pkce-verifier-0123456789abcdefghij";

let signingKey: CryptoKey;
let otherKey: CryptoKey;
let jwks: { keys: JWK[] };

beforeAll(async () => {
  const pair = await generateKeyPair("RS256", { extractable: true });
  signingKey = pair.privateKey;
  otherKey = (await generateKeyPair("RS256", { extractable: true })).privateKey;
  jwks = { keys: [{ ...(await exportJWK(pair.publicKey)), kid: "access", alg: "RS256", use: "sig" }] };
});

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("reviewer@test.invalid", { reviewer: true });
  await addPerson("gone@test.invalid", { disabled: true });
});

const doorEnv = (): Env => ({ ...testEnv, ACCESS_SAAS_CLIENT_ID: SAAS_CLIENT, ACCESS_SAAS_CLIENT_SECRET: "saas-secret" });

// ---------- the browser door

function accessToken(aud: string, email = "owner@test.invalid", key = signingKey) {
  return new SignJWT({ email }).setProtectedHeader({ alg: "RS256", kid: "access" }).setIssuer(TEAM).setAudience(aud).setIssuedAt().setExpirationTime("5m").sign(key);
}

async function browser(path: string, jwt: string) {
  let rendered = false;
  const response = await gate(
    new Request(`https://carrel.test${path}`, { headers: { "Cf-Access-Jwt-Assertion": jwt } }),
    testEnv,
    async () => {
      rendered = true;
      return new Response("inside");
    },
    createLocalJWKSet(jwks),
  );
  return { status: response.status, rendered };
}

describe("the browser door", () => {
  it("lets the browser's Access token in", async () => {
    expect(await browser("/", await accessToken(BROWSER_AUD))).toEqual({ status: 200, rendered: true });
  });

  it("PLANT: a token from any other Access application is refused, the retired MCP Access app's included", async () => {
    expect(await browser("/", await accessToken("test-mcp-audience-tag"))).toEqual({ status: 403, rendered: false });
  });

  it("PLANT: a reviewer is refused at the browser door", async () => {
    expect(await browser("/", await accessToken(BROWSER_AUD, "reviewer@test.invalid"))).toEqual({ status: 403, rendered: false });
  });

  it("PLANT: /mcp on the browser's host is a page behind Access like any other, never the AI door", async () => {
    expect(isMcpHost(new Request("https://carrel.test/mcp"), testEnv)).toBe(false);
    expect(await browser("/mcp", "")).toEqual({ status: 403, rendered: false });
  });
});

describe("which door", () => {
  it("is decided by the hostname alone", () => {
    expect(isMcpHost(new Request(`${DOOR}/mcp`), testEnv)).toBe(true);
    expect(isMcpHost(new Request(`${DOOR}/p/x/e/y`), testEnv)).toBe(true);
    expect(isMcpHost(new Request(`https://CARREL-MCP.test/mcp`), testEnv)).toBe(true);
    for (const url of ["https://carrel.test/mcp", "https://carrel-mcp.test.evil.example/mcp", "https://evil.example/carrel-mcp.test/mcp", "http://carrel-mcp.test:8443/mcp"]) {
      expect(isMcpHost(new Request(url), testEnv), url).toBe(false);
    }
  });
});

// ---------- the AI door

type Jar = Map<string, string>;

function remember(jar: Jar, response: Response) {
  for (const cookie of response.headers.getSetCookie()) {
    const [pair] = cookie.split(";");
    const at = pair!.indexOf("=");
    jar.set(pair!.slice(0, at), pair!.slice(at + 1));
  }
}

function cookieHeader(jar: Jar): string {
  return [...jar].map(([k, v]) => `${k}=${v}`).join("; ");
}

async function s256(value: string) {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)));
  return btoa(String.fromCharCode(...digest)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

type IdClaims = { email?: string; nonce?: string; aud?: string; iss?: string; key?: CryptoKey; email_verified?: boolean };

/** The fake Access for SaaS (and the client's CIMD document), behind the stubbed fetch. */
function fakeAccess(claims: (nonce: string) => IdClaims) {
  let nonce = "";
  const seen: string[] = [];
  const fetch = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    seen.push(`${request.method} ${request.url}`);
    if (request.url === CLIENT_ID) {
      return Response.json({
        client_id: CLIENT_ID,
        client_name: "Claude Code",
        redirect_uris: [REDIRECT],
        grant_types: ["authorization_code", "refresh_token"],
        response_types: ["code"],
        token_endpoint_auth_method: "none",
      });
    }
    if (request.url === `${SAAS_ISSUER}/jwks`) return Response.json(jwks);
    if (request.url === `${SAAS_ISSUER}/token` && request.method === "POST") {
      const form = new URLSearchParams(await request.text());
      if (form.get("client_secret") !== "saas-secret" || form.get("code") !== "access-code" || !form.get("code_verifier")) return Response.json({ error: "invalid_grant" }, { status: 400 });
      const c = claims(nonce);
      const jwt = new SignJWT({ email: c.email ?? "owner@test.invalid", nonce: c.nonce ?? nonce, ...(c.email_verified === undefined ? {} : { email_verified: c.email_verified }) })
        .setProtectedHeader({ alg: "RS256", kid: "access" })
        .setIssuer(c.iss ?? SAAS_ISSUER)
        .setAudience(c.aud ?? SAAS_CLIENT)
        .setIssuedAt()
        .setExpirationTime("5m");
      return Response.json({ id_token: await jwt.sign(c.key ?? signingKey), access_token: "access-access-token", token_type: "Bearer" });
    }
    throw new Error(`the fake Access does not answer ${request.method} ${request.url}`);
  });
  return { fetch, seen, setNonce: (n: string) => (nonce = n) };
}

async function door(request: Request, env: Env = doorEnv()) {
  return aiDoor(request, env, createExecutionContext());
}

/**
 * Walks the whole sign-in. Returns the final redirect to the client (with a code, or an error), and
 * the Access authorization URL the browser was sent to.
 */
async function signIn(claims: (nonce: string) => IdClaims = () => ({}), opts: { decision?: "approve" | "deny"; accessError?: boolean } = {}) {
  const access = fakeAccess(claims);
  vi.stubGlobal("fetch", access.fetch);
  const jar: Jar = new Map();
  const authorize = new URL(`${DOOR}/authorize`);
  authorize.search = new URLSearchParams({
    response_type: "code",
    client_id: CLIENT_ID,
    redirect_uri: REDIRECT,
    state: "client-state",
    code_challenge: await s256(VERIFIER),
    code_challenge_method: "S256",
    scope: "carrel",
    resource: RESOURCE,
  }).toString();
  const page = await door(new Request(authorize));
  expect(page.status, await page.clone().text()).toBe(200);
  // The consent page is HTML: untransformed, so Web Analytics cannot inject its beacon into it.
  expect(page.headers.get("cache-control")).toBe("no-store, no-transform");
  remember(jar, page);
  const html = await page.text();
  expect(html).toContain("Allow Claude Code to use Carrel as you?");
  expect(html).toContain("client.test");
  const handle = /name="handle" value="([^"]+)"/.exec(html)![1]!;

  const approve = await door(
    new Request(`${DOOR}/authorize`, {
      method: "POST",
      headers: { Cookie: cookieHeader(jar), "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ handle, decision: opts.decision ?? "approve" }),
    }),
  );
  expect(approve.status).toBe(302);
  remember(jar, approve);
  const toAccess = new URL(approve.headers.get("Location")!);
  if (opts.decision === "deny") return { final: toAccess, toAccess: null, access };

  expect(toAccess.origin + toAccess.pathname).toBe(`${SAAS_ISSUER}/authorization`);
  access.setNonce(toAccess.searchParams.get("nonce")!);
  const back = new URL(`${DOOR}/callback`);
  back.searchParams.set("state", toAccess.searchParams.get("state")!);
  if (opts.accessError) back.searchParams.set("error", "access_denied");
  else back.searchParams.set("code", "access-code");
  const done = await door(new Request(back, { headers: { Cookie: cookieHeader(jar) } }));
  expect(done.status).toBe(302);
  return { final: new URL(done.headers.get("Location")!), toAccess, access };
}

async function tokenFor(code: string): Promise<string> {
  const response = await door(
    new Request(`${DOOR}/token`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ grant_type: "authorization_code", code, redirect_uri: REDIRECT, client_id: CLIENT_ID, code_verifier: VERIFIER, resource: RESOURCE }),
    }),
  );
  const body = (await response.json()) as { access_token?: string };
  expect(response.status, JSON.stringify(body)).toBe(200);
  return body.access_token!;
}

async function callTool(token: string, name: string, args: Record<string, unknown> = {}, env?: Env): Promise<{ status: number; result?: ToolCallResult }> {
  const response = await door(modernRequest(7, "tools/call", { name, arguments: args }, { Authorization: `Bearer ${token}` }), env);
  if (response.status !== 200) return { status: response.status };
  return { status: 200, result: (await readMessage(response)).result as unknown as ToolCallResult };
}

describe("the AI door's OAuth surface", () => {
  it("answers /mcp without a token with a Bearer challenge that points at its metadata", async () => {
    const response = await door(modernRequest(1, "tools/list"));
    expect(response.status).toBe(401);
    expect(response.headers.get("WWW-Authenticate")).toContain(`resource_metadata="${DOOR}/.well-known/oauth-protected-resource/mcp"`);
    const meta = (await (await door(new Request(`${DOOR}/.well-known/oauth-protected-resource/mcp`))).json()) as Record<string, unknown>;
    expect(meta).toMatchObject({ resource: RESOURCE, authorization_servers: [DOOR] });
  });

  it("advertises CIMD and no registration endpoint, and /register does not exist", async () => {
    const meta = (await (await door(new Request(`${DOOR}/.well-known/oauth-authorization-server`))).json()) as Record<string, unknown>;
    expect(meta.client_id_metadata_document_supported).toBe(true);
    expect(meta.registration_endpoint).toBeUndefined();
    const register = await door(new Request(`${DOOR}/register`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ redirect_uris: [REDIRECT] }) }));
    expect(register.status).toBe(404);
  });

  it("PLANT: never serves Carrel's pages", async () => {
    for (const path of ["/", "/p/de-info", "/p/de-info/e/post-one/unpublish", "/social"]) {
      expect((await door(new Request(`${DOOR}${path}`))).status, path).toBe(404);
    }
  });

  it("PLANT: stays shut until the Access for SaaS app is configured", async () => {
    const response = await door(new Request(`${DOOR}/authorize?client_id=${encodeURIComponent(CLIENT_ID)}`), testEnv);
    expect(response.status).toBe(503);
  });
});

describe("signing in through Access for SaaS", () => {
  it("an Owner signs in, and the grant reaches the tools as that person, credited to the client", async () => {
    const { final, toAccess } = await signIn();
    expect(toAccess!.searchParams.get("client_id")).toBe(SAAS_CLIENT);
    expect(toAccess!.searchParams.get("redirect_uri")).toBe(`${DOOR}/callback`);
    expect(toAccess!.searchParams.get("code_challenge_method")).toBe("S256");
    expect(final.origin + final.pathname).toBe(REDIRECT);
    expect(final.searchParams.get("state")).toBe("client-state");
    const token = await tokenFor(final.searchParams.get("code")!);

    await addProject("de-info", "dustinedwards");
    const { result } = await callTool(token, "list_projects");
    expect(result!.structuredContent).toMatchObject({ projects: [{ slug: "de-info", role: "owner" }] });

    // The client is credited by its CIMD name on what it writes.
    const site = fakeSite();
    await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: One\n---\nWords.\n", expectedVersion: null, changeId: "seed" });
    const env = connectedEnv({ ACCESS_SAAS_CLIENT_ID: SAAS_CLIENT, ACCESS_SAAS_CLIENT_SECRET: "saas-secret" });
    vi.stubGlobal("fetch", site.fetch);
    await callTool(token, "add_finding", { project: "de-info", item: "post-one", message: "A flag." }, env);
    expect(await testEnv.DB.prepare("SELECT message FROM findings").first()).toEqual({ message: "A flag. (from Claude Code)" });
  });

  it("PLANT: OAuth is unchanged while an agent key is configured: the grant is still the person, an Owner here, never an agent", async () => {
    const { final } = await signIn();
    const token = await tokenFor(final.searchParams.get("code")!);
    await addProject("de-info", "dustinedwards");
    await addPerson("agent:grok");
    const withKey = connectedEnv({ ACCESS_SAAS_CLIENT_ID: SAAS_CLIENT, ACCESS_SAAS_CLIENT_SECRET: "saas-secret", AGENT_KEY_GROK: "grok-test-key-0123456789abcdefghijklmnop" });
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const { status, result } = await callTool(token, "list_projects", {}, withKey);
    expect(status).toBe(200);
    expect(result!.structuredContent).toMatchObject({ projects: [{ slug: "de-info", role: "owner" }] });
    await callTool(token, "add_finding", { project: "de-info", item: "post-one", message: "A flag." }, withKey);
    expect(await testEnv.DB.prepare("SELECT message FROM findings").first()).toEqual({ message: "A flag. (from Claude Code)" });
    // And a token that is not a grant is still refused by the provider, not read as an agent key.
    expect((await callTool("not-a-token", "list_projects", {}, withKey)).status).toBe(401);
  });

  it("PLANT: Access let someone in whom Carrel does not know: refused, no code", async () => {
    const { final } = await signIn(() => ({ email: "stranger@test.invalid" }));
    expect(final.searchParams.get("error")).toBe("access_denied");
    expect(final.searchParams.get("error_description")).toBe("This person is not in Carrel.");
    expect(final.searchParams.get("code")).toBeNull();
  });

  it("PLANT: a disabled person is refused at sign-in", async () => {
    const { final } = await signIn(() => ({ email: "gone@test.invalid" }));
    expect(final.searchParams.get("error")).toBe("access_denied");
  });

  it("PLANT: an ID token with the wrong nonce, the wrong audience, a foreign key or an unverified email is refused", async () => {
    for (const claims of [
      { nonce: "replayed" },
      { aud: "some-other-saas-app" },
      { iss: `${TEAM}/cdn-cgi/access/sso/oidc/other` },
      { key: otherKey },
      { email_verified: false },
    ] satisfies IdClaims[]) {
      const { final } = await signIn(() => claims);
      expect(final.searchParams.get("error"), JSON.stringify(claims)).toBe("access_denied");
      expect(final.searchParams.get("code")).toBeNull();
    }
  });

  it("PLANT: Access reporting an error, and a person who clicks Deny, end with access_denied", async () => {
    expect((await signIn(undefined, { accessError: true })).final.searchParams.get("error")).toBe("access_denied");
    const denied = await signIn(undefined, { decision: "deny" });
    expect(denied.final.searchParams.get("error")).toBe("access_denied");
    expect(denied.access.seen.some((s) => s.includes("/token"))).toBe(false);
  });

  it("PLANT: a person disabled after the grant loses the door at once", async () => {
    const { final } = await signIn();
    const token = await tokenFor(final.searchParams.get("code")!);
    expect((await callTool(token, "list_projects")).status).toBe(200);
    await testEnv.DB.prepare("UPDATE people SET disabled_at = '2026-09-27T00:00:00Z' WHERE email = 'owner@test.invalid'").run();
    expect((await callTool(token, "list_projects")).status).toBe(403);
  });

  it("PLANT: a grant follows the person, not the email: the email moved to a new person row is refused", async () => {
    const { final } = await signIn();
    const token = await tokenFor(final.searchParams.get("code")!);
    expect((await callTool(token, "list_projects")).status).toBe(200);
    // The same email, now a different person (the row was replaced): the old grant must not carry over.
    await testEnv.DB.prepare("UPDATE people SET id = id + 1000 WHERE email = 'owner@test.invalid'").run();
    expect((await callTool(token, "list_projects")).status).toBe(403);
  });

  it("PLANT: a reviewer signs in through the same door and is refused a publish", async () => {
    const { final } = await signIn(() => ({ email: "reviewer@test.invalid" }));
    const token = await tokenFor(final.searchParams.get("code")!);
    const id = await addProject("de-info", "dustinedwards");
    const reviewer = await testEnv.DB.prepare("SELECT id FROM people WHERE email = 'reviewer@test.invalid'").first<{ id: number }>();
    await share(id, reviewer!.id, "reader");
    const { result } = await callTool(token, "publish", { project: "de-info", item: "post-one", expected_version: "v1" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "A reviewer never publishes." }] });
  });

  it("PLANT: a forged or foreign bearer token is refused", async () => {
    expect((await callTool("not-a-token", "list_projects")).status).toBe(401);
    expect((await callTool(await accessToken(BROWSER_AUD), "list_projects")).status).toBe(401);
  });
});

